/** Functional interface allowing a lambda that can throw checked exceptions. */
@FunctionalInterface
private interface ThrowingRunnable {
    void run() throws Exception;
}

/** Simple replacement for JUnit 5's {@code assertDoesNotThrow}. */
private static void assertDoesNotThrow(ThrowingRunnable runnable, String message) {
    try {
        runnable.run();
    } catch (Throwable t) {
        fail(message + ": " + t);
    }
}

