/**
 * Creates a {@link JsonReader} positioned at the start of an array containing a single
 * {@code 1.5} value.
 *
 * @return a {@link JsonReader} ready to read the array element.
 * @throws IOException if an I/O error occurs.
 */
private JsonReader createReaderAtArrayStart() throws IOException {
  JsonReader reader = new JsonReader(reader("[1.5]"));
  reader.beginArray();
  return reader;
}

