/**
 * Verifies that calling {@code nextInt()} on a value that is not an integer throws a
 * {@link NumberFormatException}.
 */
@Test
public void testIntegerMismatchFailuresDoNotAdvance_intThrows() throws IOException {
  JsonReader reader = createReaderAtArrayStart();
  assertThrows(
      NumberFormatException.class,
      () -> reader.nextInt());
}

/**
 * Verifies that after a failed {@code nextInt()} call the reader has not advanced,
 * allowing the subsequent {@code nextDouble()} call to read the same value.
 */
@Test
public void testIntegerMismatchFailuresDoNotAdvance_readerAdvancesAfterFailure() throws IOException {
  JsonReader reader = createReaderAtArrayStart();
  // The call should fail but must not move the cursor forward.
  assertThrows(
      NumberFormatException.class,
      () -> reader.nextInt());

  // The reader is still positioned at the same value; it should be readable as a double.
  assertThat(reader.nextDouble())
      .as("Reader should still be positioned at the original element after a failed nextInt()")
      .isEqualTo(1.5d);

  // Ensure the array can be closed normally.
  reader.endArray();
}

