private interface JsonWriterConsumer {
    void accept(JsonWriter jw) throws IOException;
}

/**
 * Writes a JSON object with the provided content and returns its string representation.
 *
 * @param consumer lambda that writes the inner content of the JSON object.
 * @return the pretty‑printed JSON string.
 */
private String writePrettyJson(JsonWriterConsumer consumer) throws IOException {
    StringWriter stringWriter = new StringWriter();
    JsonWriter jsonWriter = new JsonWriter(stringWriter);
    jsonWriter.setIndent("   ");
    jsonWriter.beginObject();
    consumer.accept(jsonWriter);
    jsonWriter.endObject();
    return stringWriter.toString();
}

/* --------------------------- Refactored Tests --------------------------- */

@Test
public void testPrettyPrintObject_BasicValues() throws IOException {
    String actual = writePrettyJson(jw -> {
        jw.name("a").value(true);
        jw.name("b").value(false);
        jw.name("c").value(5.0);
        jw.name("e").nullValue();
    });

    String expected =
        "{\n"
            + "   \"a\": true,\n"
            + "   \"b\": false,\n"
            + "   \"c\": 5.0,\n"
            + "   \"e\": null\n"
            + "}";

    assertThat(actual).isEqualTo(expected);
}

@Test
public void testPrettyPrintObject_Array() throws IOException {
    String actual = writePrettyJson(jw -> {
        jw.name("f").beginArray();
        jw.value(6.0);
        jw.value(7.0);
        jw.endArray();
    });

    String expected =
        "{\n"
            + "   \"f\": [\n"
            + "      6.0,\n"
            + "      7.0\n"
            + "   ]\n"
            + "}";

    assertThat(actual).isEqualTo(expected);
}

@Test
public void testPrettyPrintObject_NestedObject() throws IOException {
    String actual = writePrettyJson(jw -> {
        jw.name("g").beginObject();
        jw.name("h").value(8.0);
        jw.name("i").value(9.0);
        jw.endObject();
    });

    String expected =
        "{\n"
            + "   \"g\": {\n"
            + "      \"h\": 8.0,\n"
            + "      \"i\": 9.0\n"
            + "   }\n"
            + "}";

    assertThat(actual).isEqualTo(expected);
}

