public void testNewsHomepage(@TempDir File tempDir) throws IOException {
    // Load the original resource file
    File original = getFile("/htmltests/news-com-au-home.html");
    // Verify the resource file exists (Resource Optimism)
    assertTrue("Resource file should exist: " + original.getPath(),
            original.exists() && original.isFile());

    // Copy the resource file into the temporary directory (Mystery Guest)
    File in = new File(tempDir, original.getName());
    Files.copy(original.toPath(), in.toPath());

    // Verify the copied file exists
    assertTrue("Copied file should exist: " + in.getPath(),
            in.exists() && in.isFile());

    Document doc = Jsoup.parse(in, "UTF-8", "http://www.news.com.au/");
    // Assertion messages added for clarity (Assertion Roulette)
    assertEquals("Page title should match expected",
            "News.com.au | News from Australia and around the world online | NewsComAu",
            doc.title());
    assertEquals("Headline text should match expected",
            "Brace yourself for Metro meltdown",
            doc.select(".id1225817868581 h4").text().trim());

    Element a = doc.select("a[href=/entertainment/horoscopes]").first();
    assertNotNull("Link element with href /entertainment/horoscopes should be present", a);
    assertEquals("Link href attribute should be exact path",
            "/entertainment/horoscopes", a.attr("href"));
    assertEquals("Absolute href should be resolved correctly",
            "http://www.news.com.au/entertainment/horoscopes", a.attr("abs:href"));

    Element hs = doc.select("a[href*=naughty-corners-are-a-bad-idea]").first();
    assertNotNull("Link element with href containing naughty-corners-are-a-bad-idea should be present", hs);
    assertEquals("Href should match expected absolute URL",
            "http://www.heraldsun.com.au/news/naughty-corners-are-a-bad-idea-for-kids/story-e6frf7jo-1225817899003",
            hs.attr("href"));
    assertEquals("Absolute href should be same as href for this element",
            hs.attr("href"), hs.attr("abs:href"));
}

