@Test
public void testIteratorHasNext() {
    Attributes a = new Attributes();
    a.put("Tot", "1");
    a.put("Hello", "2");
    a.put("data-name", "3");

    verifyAttributesIteration(a);
}

private void verifyAttributesIteration(Attributes attrs) {
    int seen = 0;
    for (Attribute attribute : attrs) {
        seen++;
        assertEquals("Attribute value at index " + seen,
                String.valueOf(seen), attribute.getValue());
    }
    assertEquals("Total number of attributes should be " + EXPECTED_ATTRIBUTE_COUNT,
            EXPECTED_ATTRIBUTE_COUNT, seen);
}

