            + "<input name='seven' type='radio' value='on' checked><input name='seven' type='radio' value='off'>"
            + "<input name='eight' type='checkbox' checked><input name='nine' type='checkbox' value='unset'>"
            + "<input name='ten' value='text' disabled>"
            + "<input name='eleven' value='text' type='button'>"
            + "</form>";
    Document doc = Jsoup.parse(html);
    FormElement form = (FormElement) doc.select("form").first();
    List<Connection.KeyVal> data = form.formData();

    final int EXPECTED_FORM_DATA_SIZE = 6;
    assertEquals("Form data size should be 6", EXPECTED_FORM_DATA_SIZE, data.size());

    // Entry 0
    Connection.KeyVal kv0 = data.get(0);
    assertEquals("First entry key should be 'one'", "one", kv0.key());
    assertEquals("First entry value should be 'two'", "two", kv0.value());

    // Entry 1
    Connection.KeyVal kv1 = data.get(1);
    assertEquals("Second entry key should be 'three'", "three", kv1.key());
    assertEquals("Second entry value should be 'four'", "four", kv1.value());

    // Entry 2
    Connection.KeyVal kv2 = data.get(2);
    assertEquals("Third entry key should be 'three'", "three", kv2.key());
    assertEquals("Third entry value should be 'five'", "five", kv2.value());

    // Entry 3
    Connection.KeyVal kv3 = data.get(3);
    assertEquals("Fourth entry key should be 'six'", "six", kv3.key());
    assertEquals("Fourth entry value should be 'seven'", "seven", kv3.value());

    // Entry 4
    Connection.KeyVal kv4 = data.get(4);
    assertEquals("Fifth entry key should be 'seven'", "seven", kv4.key());
    assertEquals("Fifth entry value should be 'on'", "on", kv4.value());

    // Entry 5
    Connection.KeyVal kv5 = data.get(5);
    assertEquals("Sixth entry key should be 'eight'", "eight", kv5.key());
    assertEquals("Sixth entry value should be 'on'", "on", kv5.value());

    // nine should not appear, not checked checkbox
    // ten should not appear, disabled
    // eleven should not appear, button
}

