private static class OwnerDocumentSetup {
    final Document doc;
    final Element p;

    OwnerDocumentSetup(Document doc, Element p) {
        this.doc = doc;
        this.p = p;
    }
}

private OwnerDocumentSetup setupTestOwnerDocument() {
    Document doc = Jsoup.parse("<p>Hello");
    Element p = doc.select("p").first();
    return new OwnerDocumentSetup(doc, p);
}

@Test
public void ownerDocument_elementOwnerDocument() {
    OwnerDocumentSetup ctx = setupTestOwnerDocument();
    assertTrue("Element's ownerDocument should be the same Document instance", ctx.p.ownerDocument() == ctx.doc);
}

@Test
public void ownerDocument_documentOwnerDocument() {
    OwnerDocumentSetup ctx = setupTestOwnerDocument();
    assertTrue("Document's ownerDocument should return itself", ctx.doc.ownerDocument() == ctx.doc);
}

@Test
public void ownerDocument_documentParentIsNull() {
    OwnerDocumentSetup ctx = setupTestOwnerDocument();
    assertNull("Document's parent should be null", ctx.doc.parent());
}

